export async function maybeAutoDeploySprintBatchPr(opts: {
  jobId: string
  userId: string
  productId: string
  sprintRunId: string
}): Promise<void> {
  const { jobId, userId, productId, sprintRunId } = opts

  // (1) Level check
  const run = await prisma.sprintRun.findUnique({
    where: { id: sprintRunId },
    select: { status: true, product: { select: { repo_url: true } } },
  })
  if (run?.status !== 'DONE') return
  const productRepoUrl = run.product?.repo_url ?? null

  // (2) Product repo batch PR resolve
  const prJobs = await prisma.claudeJob.findMany({
    where: { sprint_run_id: sprintRunId, pr_url: { not: null } },
    orderBy: { created_at: 'asc' },
    select: { pr_url: true, head_sha: true, task: { select: { repo_url: true } } },
  })
  const productPrJob = prJobs.find(
    (j) => repoBucketKey(j.task?.repo_url ?? null, productRepoUrl) === null,
  )
  if (!productPrJob) {
    console.warn(`[maybeAutoDeploySprintBatchPr] job=${jobId}: geen product-repo-PR in sprint_run ${sprintRunId} — skip`)
    return
  }
  const prUrl = productPrJob.pr_url!

  // (3) head sha — self-resolving, no cross-repo leak
  let headSha: string | null = productPrJob.head_sha ?? null
  if (!headSha) {
    const state = await getPullRequestState({ prUrl })
    headSha = 'headSha' in state ? state.headSha : null
  }
  if (!headSha) {
    console.warn(`[maybeAutoDeploySprintBatchPr] job=${jobId}: geen head-sha voor ${prUrl} — skip`)
    return
  }

  // (4a) Preflight
  const eligibility = await checkDeployEligibility(productId)
  if (eligibility.outcome === 'not_configured') return
  if (eligibility.outcome === 'blocked') {
    console.warn(`[maybeAutoDeploySprintBatchPr] job=${jobId}: deploy geblokkeerd (${eligibility.reasons.join(', ')})`)
    void triggerPush(userId, {
      title: 'Sprint-batch auto-deploy geblokkeerd',
      body: eligibility.reasons.join(', ').slice(0, 120),
      url: prUrl,
      tag: `sprint-batch-deploy-${jobId}`,
    })
    return
  }

  // (4c) ENABLE_AUTO_MERGE
  const outcomes = await executeEffects([
    { type: 'ENABLE_AUTO_MERGE', prUrl, expectedHeadSha: headSha },
  ])
  const enabled = outcomes.find((o) => o.effect === 'ENABLE_AUTO_MERGE')
  if (!enabled?.ok) {
    console.warn(`[maybeAutoDeploySprintBatchPr] job=${jobId}: auto-merge enable faalde: ${enabled ? `${enabled.reason} ${enabled.stderr.slice(0, 200)}` : 'geen outcome'}`)
    void triggerPush(userId, {
      title: 'Sprint-batch auto-merge-enable mislukt',
      body: (enabled ? `${enabled.reason}: ${enabled.stderr.slice(0, 80)}` : 'enable faalde').slice(0, 120),
      url: prUrl,
      tag: `sprint-batch-deploy-${jobId}`,
    })
    return
  }

  // (4d) Enqueue + 2nd check observability
  try {
    const outcome = await maybeEnqueueDeployJob({
      parentJobId: jobId, userId, productId, prUrl, headSha,
    })
    if (outcome === 'not_configured' || outcome === 'blocked') {
      console.warn(`[maybeAutoDeploySprintBatchPr] job=${jobId}: deploy-enqueue ${outcome} ná ok-enable (race)`)
      void triggerPush(userId, {
        title: 'Sprint-batch deploy niet enqueued',
        body: `auto-merge was enabled maar deploy niet enqueued (${outcome})`.slice(0, 120),
        url: prUrl,
        tag: `sprint-batch-deploy-${jobId}`,
      })
    }
  } catch (err) {
    console.error('[maybeAutoDeploySprintBatchPr] deploy-enqueue faalde:', err)
    void triggerPush(userId, {
      title: 'Sprint-batch deploy-enqueue mislukt',
      body: (err instanceof Error ? err.message : String(err)).slice(0, 120),
      url: prUrl,
      tag: `sprint-batch-deploy-${jobId}`,
    })
  }
}
